from pathlib import Path
import pandas as pd,numpy as np,sqlite3,json,datetime,hashlib
root=Path(__file__).resolve().parent.parent/'jansen-etf/selected'; out=Path(__file__).resolve().parent
db=sqlite3.connect((root/'registry.db').as_uri()+'?mode=ro',uri=True);db.row_factory=sqlite3.Row
runs=[];details={}
for p in sorted((root/'backtest').iterdir()):
 if not p.is_dir():continue
 name=p.name;spec=json.loads((p/'spec.json').read_text());initial=spec['backtest_config']['cash']['initial'];eq=pd.read_parquet(p/'equity.parquet');f=pd.read_parquet(p/'fills.parquet');t=pd.read_parquet(p/'trades.parquet');ps=pd.read_parquet(p/'portfolio_state.parquet');dr=pd.read_parquet(p/'daily_returns.parquet');w=pd.read_parquet(p/'weights.parquet')
 row=db.execute('''select b.backtest_hash,b.stage,b.prediction_hash,b.created_at,b.git_commit,p.split,p.training_hash,t.family,t.config_name,m.total_return,m.max_drawdown,m.sharpe,m.total_commission,m.total_slippage,m.num_trades from backtest_runs b join prediction_sets p on b.prediction_hash=p.prediction_hash join training_runs t on p.training_hash=t.training_hash join backtest_metrics m on m.backtest_hash=b.backtest_hash where b.backtest_hash=?''',(name,)).fetchone();r=dict(row)
 r.update(start=str(eq.timestamp.iloc[0]),end=str(eq.timestamp.iloc[-1]),initial_cash=initial,first_saved_equity=float(eq.equity.iloc[0]),final_equity=float(eq.equity.iloc[-1]),equity_delta_from_initial_cash=float(eq.equity.iloc[-1]-initial),return_from_initial_cash=float(eq.equity.iloc[-1]/initial-1),return_from_first_saved_equity=float(eq.equity.iloc[-1]/eq.equity.iloc[0]-1),saved_8h_max_drawdown=float(eq.drawdown.min()),saved_daily_return_compound=float((1+dr.daily_return).prod()-1),fills_rows=len(f),trades_rows=len(t),equity_rows=len(eq),weights_rows=len(w),assets=int(f.asset.nunique()))
 delta=eq.equity.iloc[-1]-initial;fc=float((np.where(f.side.eq('sell'),1.,-1.)*f.quantity*f.price-f.commission).sum()); inferred_funding=float(ps.cash.iloc[-1]-initial-fc)
 r['reconciliation']={'commission_from_fills':float(f.commission.sum()),'commission_minus_registry':float(f.commission.sum()-r['total_commission']),'slippage_money_from_fills_declared_slippage_field':float((f.quantity*f.slippage).sum()),'slippage_minus_registry':float((f.quantity*f.slippage).sum()-r['total_slippage']),'price_reference_gap_money_not_assumed_slippage':float((f.quantity*abs(f.price-f.reference_price)).sum()),'sum_trade_pnl':float(t.pnl.sum()),'sum_trade_fees':float(t.fees.sum()),'sum_trade_gross_pnl':float(t.gross_pnl.sum()),'sum_trade_slippage':float(t.total_slippage_cost.sum()),'trade_pnl_minus_equity_delta':float(t.pnl.sum()+0.0-delta),'fills_net_cashflow_excluding_funding':fc,'unexplained_cash_residual_after_fills':inferred_funding,'cash_residual':float(inferred_funding-0.0),'cash_plus_net_exposure_minus_equity_max_abs':float((ps.cash+ps.net_exposure-ps.equity).abs().max()),'final_cash':float(ps.cash.iloc[-1]),'final_net_exposure':float(ps.net_exposure.iloc[-1]),'final_gross_exposure':float(ps.gross_exposure.iloc[-1]),'final_open_position_count':int(ps.open_positions.iloc[-1]),'max_gross_exposure_over_equity':float((ps.gross_exposure/ps.equity).max())}
 runs.append(r)
 if name in ['18c7a8419306','89e706faf2fe']:
  ff=f.copy();ff['signed_qty']=np.where(ff.side.eq('buy'),1.,-1.)*ff.quantity
  q=ff.pivot_table(index='timestamp',columns='asset',values='signed_qty',aggfunc='sum',fill_value=0).reindex(pd.Index(eq.timestamp),fill_value=0).cumsum()
  counts=(q.abs()>1e-7).sum(axis=1).to_numpy(); errs=counts-ps.open_positions.to_numpy()
  train=json.loads(db.execute('select spec_json from training_runs where training_hash=?',(r['training_hash'],)).fetchone()[0]);
  details[name]={'schemas':{fn:{'rows':len(d),'columns':list(d.columns),'nulls':{k:int(v) for k,v in d.isna().sum().to_dict().items()}} for fn,d in [('weights.parquet',w),('fills.parquet',f),('trades.parquet',t),('portfolio_state.parquet',ps),('equity.parquet',eq),('daily_returns.parquet',dr)]},'trade_status_counts':t.status.value_counts().to_dict(),'final_holdings_quantities_reconstructed_from_fills':{a:float(v) for a,v in q.iloc[-1].items() if abs(v)>1e-7},'position_count_max_absolute_difference_from_signed_fills':int(abs(errs).max()),'position_count_mismatch_rows':int((errs!=0).sum()),'training_cv':train.get('computation',{}).get('cv'),'execution_and_economic_spec':{'execution':spec['backtest_config']['execution'],'commission':spec['backtest_config']['commission'],'slippage':spec['backtest_config']['slippage'],'economic_cashflows':spec.get('economic_cashflows'),'risk':spec['strategy'].get('risk')},'file_sha256':{x.name:hashlib.sha256(x.read_bytes()).hexdigest() for x in p.iterdir() if x.is_file()}}
  # This is a cash reconciliation residual, not an original funding ledger or a newly simulated strategy.
  cashlegs=ff.assign(cashflow=np.where(ff.side.eq('sell'),1.,-1.)*ff.quantity*ff.price-ff.commission).groupby('timestamp').cashflow.sum().reindex(pd.Index(ps.timestamp),fill_value=0)
  cashchange=ps.cash.diff();cashchange.iloc[0]=ps.cash.iloc[0]-initial
  residual=pd.DataFrame({'timestamp':ps.timestamp,'saved_cash_change':cashchange,'fills_cashflow_net_excluding_funding':cashlegs.to_numpy(),'unexplained_cashflow_residual_after_saved_fills':cashchange.to_numpy()-cashlegs.to_numpy()})
  residual.to_csv(out/(name+'-cash-reconciliation-residual.csv'),index=False)
summary={'scope':'Static audit of saved Parquet and read-only SQLite SELECT only. No repository code, model, backtest, market-data returns, or new strategy paths executed.','read_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'counts':{'saved_backtests':len(runs),'split_validation':sum(r['split']=='validation' for r in runs),'split_holdout':sum(r['split']=='holdout' for r in runs)},'release_selected_run_from_parent':'18c7a8419306','selected_run_is':'validation risk_overlay, not heldout test','holdout_run':'89e706faf2fe','conclusion':'The independently labelled holdout has positive saved net account PnL, with internally reconciled fills, commissions and declared slippage. External market-data pricing and timing remain parent-audit responsibilities.','limits':['weights are timestamp/symbol/weight target data; no quantity/price/commission in weights','fills contain asset/side/quantity/price/timestamp/commission/slippage/reference_price and are simulated execution records, not broker receipts','portfolio_state stores account aggregates and open-position counts; no per-asset actual quantities','No funding applies to this ETF audit. Cash residual after fills closes without an additional ledger.','Full archive integrity, source-code signal/execution timing, corporate-action and open-price semantics, software/data permission are parent audit responsibilities. All holdout fills are marked source=open but executed price minus reference_price differs from declared slippage, so price/reference gap is not treated as slippage.','Registry total_return, saved daily-return compounding and initial-to-final equity change match for the holdout. Last two positions remain open, so final value is mark-to-market equity.','All 20 validation variants and one holdout are shown; no post-hoc positive subset selection; one two-year holdout is not proof of live profitability or broad robustness'],'runs':runs,'details':details}
(out/'audit.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False));pd.DataFrame([{k:v for k,v in r.items() if k!='reconciliation'} for r in runs]).to_csv(out/'all-21-saved-runs.csv',index=False)
print(json.dumps({'counts':summary['counts'],'details':{k:{'positions_match_rows':v['position_count_mismatch_rows'],'final_holdings':v['final_holdings_quantities_reconstructed_from_fills']} for k,v in details.items()},'max_cash_reconcile_error':max(abs(r['reconciliation']['trade_pnl_minus_equity_delta']) for r in runs)},ensure_ascii=False))
